{
  "id": "V071",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "지역별 생활 장면에 맞는 광고 이미지 후보를 준비하려는 목적이 유지됩니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "이미지 후보 준비와 담당자 검토, 승인 후 게시의 흐름이 보존됩니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "생활용품 광고 이미지와 제품 사진이 반영되어 있습니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "승인된 제품 사진이 유지 조건으로 언급됩니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "검토할 이미지 후보가 보존됩니다."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "제품 외형·브랜드 표현의 유지와 지역별 배경, 승인 후 게시가 모두 반영됩니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가한 표현이 없습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "담당자의 검토와 게시 승인 후 진행이 보존되며 역할 혼동이 없습니다."
    }
  ],
  "issues": [],
  "permission_interpretation": "담당자가 이미지 후보를 검토하며 실제 광고 게시는 승인 뒤에 진행됩니다. AI가 게시하거나 승인한다고 서술하지 않습니다."
}
